// 组件只绑定现有军团成员读口；生产World仍由BundleServices持唯一规则。
struct Members final:MembershipResolver { const ArmyRecord& army;explicit Members(const ArmyRecord& a):army(a){}const std::vector<StableId>* active_army_members(const StableId& actor)const override{return std::find(army.member_actor_ids.begin(),army.member_actor_ids.end(),actor)!=army.member_actor_ids.end()?&army.member_actor_ids:nullptr;}const StableId* army_leader(const StableId& actor)const override{return active_army_members(actor)?&army.commander_actor_id:nullptr;}};
// 只核投影及原proof真实载荷，完整Main/World另用正式银行。
int main(){try{WorldFixture f;Members members(f.military.armies.front());f.common.bind_membership(&members);for(const auto& v:f.state.vessels)f.catalog.vessels.push_back({v.id,v.hull_id,v.cargo_inventory_id,v.berth_id,v.owner,v.integrity,"name."+v.id});auto before=take(render_boundary_json(encode_common_state(f.common.state())));auto page=take(naval_camp_page(f.common,f.military,f.mc,f.access,f.state,f.catalog,"captain0"));check(boundary::get_bool(page,"can_command","page"),"actual commander can draft");check(page.find("ships")->as<BoundaryValue::Array>()->size()==2,"only own real local vessels visible");check(page.find("units")->as<BoundaryValue::Array>()->size()==2,"actual whole army units retained");check(boundary::get_int(*page.find("source"),"revision","source")==f.common.revision(),"current revision captured");auto hidden=f.state.vessels.front();hidden.id="remote";hidden.cargo_inventory_id="remote_hold";hidden.berth_id="remote_berth";f.state.vessels.push_back(hidden);page=take(naval_camp_page(f.common,f.military,f.mc,f.access,f.state,f.catalog,"captain0"));check(page.find("ships")->as<BoundaryValue::Array>()->size()==2,"remote vessel not disclosed");f.state.vessels.pop_back();auto made=take(apply_naval_command(f.common,f.military,f.mc,f.access,f.state,f.catalog,"captain0",NavalForm{"ui",f.request}));page=take(naval_camp_page(f.common,f.military,f.mc,f.access,f.state,f.catalog,"captain0"));check(boundary::get_string(page,"fleet_id","page")==made.fleet_id,"same real fleet projected");check(page.find("ships")->as<BoundaryValue::Array>()->front().find("load")!=nullptr,"actual per-vessel proof load displayed");check(page.find("history")->as<BoundaryValue::Array>()->size()==1,"one permanent formation history");auto member=take(naval_camp_page(f.common,f.military,f.mc,f.access,f.state,f.catalog,"captain1"));check(!boundary::get_bool(member,"can_command","page")&&member.find("units")->as<BoundaryValue::Array>()->empty(),"ordinary attached captain gets no commander draft");auto stable=take(render_boundary_json(encode_common_state(f.common.state())));take(naval_camp_page(f.common,f.military,f.mc,f.access,f.state,f.catalog,"captain0"));check(stable==take(render_boundary_json(encode_common_state(f.common.state()))),"view leaves Common unchanged");std::cout<<"NAVAL_VIEW_CHECKS="<<checks<<" FAILURES=0 SCOPE=TYPED_COMPONENT\n";return 0;}catch(const std::exception& e){std::cerr<<"NAVAL_VIEW_FAIL checks="<<checks<<" "<<e.what()<<'\n';return 1;}}
